alter table public.shop_settings add column if not exists treat_pair_price numeric(10,2) not null default 5 check (treat_pair_price > 0);
update public.shop_settings set treat_pair_price=5,updated_at=now() where id;

create table public.site_pages (
  slug text primary key check (slug in ('home','about')),
  draft_content jsonb not null check (jsonb_typeof(draft_content)='object'),
  published_content jsonb not null check (jsonb_typeof(published_content)='object'),
  revision bigint not null default 0,
  updated_at timestamptz not null default now(),
  published_at timestamptz not null default now()
);
alter table public.site_pages enable row level security;
revoke all on public.site_pages from public,anon,authenticated;
grant select(slug,published_content,published_at) on public.site_pages to anon,authenticated;
create policy "Visitors read published page content" on public.site_pages for select to anon,authenticated using (true);

create or replace function private.bonbons_catalog_pages(action text,payload jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $function$
declare
  p jsonb;
  result jsonb;
  current_row public.products%rowtype;
  page_row public.site_pages%rowtype;
  product_price numeric;
  stock integer;
  threshold integer;
  category_value text;
  regular_price numeric;
  pair_price numeric;
begin
  if action='page_list' then
    select coalesce(jsonb_agg(to_jsonb(s) order by slug),'[]'::jsonb) into result from public.site_pages s;
    return result;
  end if;
  if action in ('page_save','page_publish') then
    if payload->>'slug' not in ('home','about') or jsonb_typeof(payload->'content')<>'object' or octet_length((payload->'content')::text)>200000 then
      raise exception 'Enter valid Home or About page content.' using errcode='22023';
    end if;
    select * into page_row from public.site_pages where slug=payload->>'slug' for update;
    if not found then raise exception 'That page was not found.' using errcode='P0002'; end if;
    if (payload->>'revision')::bigint is distinct from page_row.revision then
      raise exception 'This page was changed in another editor. Reload its saved version before saving again.' using errcode='40001';
    end if;
    update public.site_pages s set draft_content=payload->'content',
      published_content=case when action='page_publish' then payload->'content' else s.published_content end,
      published_at=case when action='page_publish' then now() else s.published_at end,
      revision=s.revision+1,updated_at=now()
    where slug=page_row.slug returning to_jsonb(s) into result;
    return result;
  end if;
  if action='update_treat_settings' then
    regular_price=(payload->>'single_pop_price')::numeric;
    pair_price=(payload->>'treat_pair_price')::numeric;
    if regular_price is null or pair_price is null or regular_price<=0 or pair_price<=0 or regular_price>500 or pair_price>500 or pair_price>regular_price*2 or round(regular_price,2)<>regular_price or round(pair_price,2)<>pair_price then
      raise exception 'Enter valid regular and two-treat prices. The pair cannot cost more than two regular singles.' using errcode='22023';
    end if;
    update public.shop_settings s set single_pop_price=regular_price,treat_pair_price=pair_price,
      pretzel_rod_price=regular_price,pretzel_pair_price=pair_price,updated_at=now() where id returning to_jsonb(s) into result;
    update public.products set price=regular_price,updated_at=now() where bundle_eligible and deleted_at is null;
    return result;
  end if;
  if action in ('menu_create','menu_update') then
    p=payload->'product';
    product_price=(p->>'price')::numeric;
    stock=(p->>'stock_quantity')::integer;
    threshold=coalesce((p->>'low_stock_threshold')::integer,3);
    category_value=p->>'category';
    if jsonb_typeof(p)<>'object' or length(trim(coalesce(p->>'name','')))=0 or length(p->>'name')>80
      or coalesce(p->>'slug','')!~'^[a-z0-9]+(-[a-z0-9]+)*$' or length(p->>'slug')>100
      or product_price is null or product_price<=0 or product_price>500 or round(product_price,2)<>product_price
      or stock<0 or stock>100000 or threshold<0 or threshold>1000
      or category_value not in ('everyday','pretzel-rods','rice-crispy-treats','dipped-oreos','custom')
      or jsonb_typeof(p->'active')<>'boolean' or jsonb_typeof(p->'bundle_eligible')<>'boolean' then
      raise exception 'Enter valid product, category, price, visibility, and stock details.' using errcode='22023';
    end if;
    if action='menu_update' then
      select * into current_row from public.products where id=(payload->>'id')::bigint for update;
      if not found then raise exception 'That product was not found.' using errcode='P0002'; end if;
      if current_row.deleted_at is not null then raise exception 'Restore this item from Trash before editing it.' using errcode='22023'; end if;
      if (payload->>'expectedUpdatedAt')::timestamptz is distinct from current_row.updated_at then raise exception 'This product changed. Refresh the menu before saving again.' using errcode='40001'; end if;
      if p->>'slug'<>current_row.slug then raise exception 'The product link cannot change after creation.' using errcode='22023'; end if;
      update public.products product set
        name=p->>'name',blurb=coalesce(p->>'blurb',''),description=coalesce(p->>'description',''),price=product_price,unit='each',
        image=coalesce(p->>'image',''),active=(p->>'active')::boolean,bundle_eligible=(p->>'bundle_eligible')::boolean,
        category=category_value,sort_order=coalesce((p->>'sort_order')::integer,0),
        allergens=array(select jsonb_array_elements_text(coalesce(p->'allergens','[]'::jsonb))),badge=coalesce(p->>'badge',''),source_url=coalesce(p->>'source_url',''),
        stock_quantity=stock,low_stock_threshold=threshold,updated_at=clock_timestamp()
      where id=current_row.id returning to_jsonb(product) into result;
    else
      insert into public.products(slug,name,blurb,description,price,unit,image,active,bundle_eligible,category,sort_order,allergens,badge,source_url,stock_quantity,low_stock_threshold)
      values (p->>'slug',p->>'name',coalesce(p->>'blurb',''),coalesce(p->>'description',''),product_price,'each',coalesce(p->>'image',''),(p->>'active')::boolean,(p->>'bundle_eligible')::boolean,category_value,coalesce((p->>'sort_order')::integer,0),array(select jsonb_array_elements_text(coalesce(p->'allergens','[]'::jsonb))),coalesce(p->>'badge',''),coalesce(p->>'source_url',''),stock,threshold)
      returning to_jsonb(products) into result;
    end if;
    return result;
  end if;
  raise exception 'Unknown page or catalog action.' using errcode='22023';
end;
$function$;
revoke all on function private.bonbons_catalog_pages(text,jsonb) from public,anon,authenticated,service_role;

-- Preserve the existing token check and every current action. New actions are
-- reached only after the existing authenticated dispatcher accepts the token.
alter function public.bonbons_admin(text,text,jsonb) set schema private;
alter function private.bonbons_admin(text,text,jsonb) rename to bonbons_admin_legacy;
revoke all on function private.bonbons_admin_legacy(text,text,jsonb) from public,anon,authenticated,service_role;
create function public.bonbons_admin(auth_token text,action text,payload jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='' as $function$
begin
  perform private.bonbons_admin_legacy(auth_token,'get_shop_settings','{}'::jsonb);
  if action in ('page_list','page_save','page_publish','menu_create','menu_update','update_treat_settings') then
    return private.bonbons_catalog_pages(action,payload);
  end if;
  return private.bonbons_admin_legacy(auth_token,action,payload);
end;
$function$;
revoke all on function public.bonbons_admin(text,text,jsonb) from public,authenticated;
grant execute on function public.bonbons_admin(text,text,jsonb) to anon,service_role;

-- Add only the new products named in the supplied menu. Existing visibility,
-- photos, stock levels, and specialty prices are left as the owner set them.
insert into public.products(slug,name,blurb,description,price,unit,category,bundle_eligible,active,sort_order)
values
('strawberry-crunch-pretzel-rod','Strawberry Crunch Pretzel Rod','A dipped pretzel rod with a strawberry crunch finish.','Strawberry Crunch Pretzel Rod, handmade by Bon Bon’s. Ask Bonnie about ingredients and current availability.',3,'each','pretzel-rods',true,true,45),
('vanilla-dipped-rice-crispy-fall-deco','Vanilla Dipped Rice Crispy Treat with Fall Deco','A vanilla-dipped rice crispy treat with fall decorations.','Vanilla Dipped Rice Crispy Treat with Fall Deco, handmade by Bon Bon’s. Ask Bonnie about ingredients and current availability.',3,'each','rice-crispy-treats',true,true,200),
('fruity-pebble-rice-crispy-treat','Fruity Pebble Rice Crispy Treat','A dipped rice crispy treat with a Fruity Pebble finish.','Fruity Pebble Rice Crispy Treat, handmade by Bon Bon’s. Ask Bonnie about ingredients and current availability.',3,'each','rice-crispy-treats',true,true,210),
('peanut-butter-chocolate-oreo','Peanut Butter & Chocolate Oreo','A dipped Oreo with peanut butter and chocolate.','Peanut Butter & Chocolate Oreo, handmade by Bon Bon’s. Ask Bonnie about ingredients and allergens before ordering.',3,'each','dipped-oreos',true,true,220)
on conflict(slug) do nothing;

