insert into public.site_pages(slug,draft_content,published_content) values ('about','{"title":"Our story","description":"Meet Bonnie Gazmez and her supporting husband Greg Gamez. Bon Bon''s handmade treats are rooted in family, love, and Christian faith.","sections":[{"id":"hero","label":"Meet Bonnie & Greg","enabled":true,"fields":{"eyebrow":"The heart behind Bon Bon’s","heading":"A little faith.","highlight":"A lot of heart.","body":"Meet Bonnie Gazmez—the baker, believer, and creator behind Bon Bon’s Sweets & More.\n\nA lifelong love of baking, the encouragement of her husband Greg Gamez, and a God-given gift. That is where our story begins.","actionLabel":"Come into our kitchen","actionHref":"#our-story","image":"/images/bonnie-and-greg.jpg","imageAlt":"Bonnie and her supporting husband Greg Gamez","caption":"Bonnie & Greg","captionNote":"Family. Faith. Something sweet."}},{"id":"beginnings","label":"How it started","enabled":true,"fields":{"eyebrow":"01 / How it started","heading":"Always baking.","highlight":"Always sharing.","body":"For Bonnie, baking has always been about the people she loves. Long before Bon Bon’s, she was making sweet treats for her family and friends—finding joy in something homemade and the smiles that followed.\n\nOne day, she decided to turn those God-given gifts into a handmade treat business. Bon Bon’s Sweets & More grew from that simple step: sharing what she loves with a few more people."}},{"id":"faith","label":"What guides her","enabled":true,"fields":{"eyebrow":"02 / What guides her","heading":"Faith is not just part of the story.","highlight":"It is at the heart of it.","body":"Bonnie’s Christian faith is a big part of who she is. She sees her creativity and love for baking as gifts from God, and Bon Bon’s is a way to put those gifts to work with gratitude, care, and love for others."}},{"id":"family","label":"Better together","enabled":true,"fields":{"eyebrow":"03 / Better together","heading":"A dream with","highlight":"Greg by her side.","body":"Behind Bonnie is her supporting husband, Greg Gamez. His encouragement is an important part of her journey, and together they bring the warmth of family to Bon Bon’s.\n\nToday, our menu includes cake pops, pretzel rods, dipped rice crispy treats, and dipped Oreos. A little treat for yourself, two to share, or something special for a celebration—each begins with that same love of making someone’s day.","image":"/products/bonbons-real-gift-box.jpg","imageAlt":"Bonnie''s wrapped cake pops in a gift box with blue paper filling","actionLabel":"Find a little joy of your own","actionHref":"/shop"}},{"id":"closing","label":"Closing invitation","enabled":true,"fields":{"eyebrow":"From our family to you","heading":"Thanks for being part","highlight":"of our sweet beginning.","primaryLabel":"Shop all treats","primaryHref":"/shop","secondaryLabel":"Planning an event? Rent the cart","secondaryHref":"/rent-a-cart"}}]}'::jsonb,'{"title":"Our story","description":"Meet Bonnie Gazmez and her supporting husband Greg Gamez. Bon Bon''s handmade treats are rooted in family, love, and Christian faith.","sections":[{"id":"hero","label":"Meet Bonnie & Greg","enabled":true,"fields":{"eyebrow":"The heart behind Bon Bon’s","heading":"A little faith.","highlight":"A lot of heart.","body":"Meet Bonnie Gazmez—the baker, believer, and creator behind Bon Bon’s Sweets & More.\n\nA lifelong love of baking, the encouragement of her husband Greg Gamez, and a God-given gift. That is where our story begins.","actionLabel":"Come into our kitchen","actionHref":"#our-story","image":"/images/bonnie-and-greg.jpg","imageAlt":"Bonnie and her supporting husband Greg Gamez","caption":"Bonnie & Greg","captionNote":"Family. Faith. Something sweet."}},{"id":"beginnings","label":"How it started","enabled":true,"fields":{"eyebrow":"01 / How it started","heading":"Always baking.","highlight":"Always sharing.","body":"For Bonnie, baking has always been about the people she loves. Long before Bon Bon’s, she was making sweet treats for her family and friends—finding joy in something homemade and the smiles that followed.\n\nOne day, she decided to turn those God-given gifts into a handmade treat business. Bon Bon’s Sweets & More grew from that simple step: sharing what she loves with a few more people."}},{"id":"faith","label":"What guides her","enabled":true,"fields":{"eyebrow":"02 / What guides her","heading":"Faith is not just part of the story.","highlight":"It is at the heart of it.","body":"Bonnie’s Christian faith is a big part of who she is. She sees her creativity and love for baking as gifts from God, and Bon Bon’s is a way to put those gifts to work with gratitude, care, and love for others."}},{"id":"family","label":"Better together","enabled":true,"fields":{"eyebrow":"03 / Better together","heading":"A dream with","highlight":"Greg by her side.","body":"Behind Bonnie is her supporting husband, Greg Gamez. His encouragement is an important part of her journey, and together they bring the warmth of family to Bon Bon’s.\n\nToday, our menu includes cake pops, pretzel rods, dipped rice crispy treats, and dipped Oreos. A little treat for yourself, two to share, or something special for a celebration—each begins with that same love of making someone’s day.","image":"/products/bonbons-real-gift-box.jpg","imageAlt":"Bonnie''s wrapped cake pops in a gift box with blue paper filling","actionLabel":"Find a little joy of your own","actionHref":"/shop"}},{"id":"closing","label":"Closing invitation","enabled":true,"fields":{"eyebrow":"From our family to you","heading":"Thanks for being part","highlight":"of our sweet beginning.","primaryLabel":"Shop all treats","primaryHref":"/shop","secondaryLabel":"Planning an event? Rent the cart","secondaryHref":"/rent-a-cart"}}]}'::jsonb);
